#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const PACKAGE_NAME = 'sg-backend-starter';

// A csomag telepítési helye: node_modules/sg-backend-starter
const packageDir = __dirname;
// Ahol npm install fut (a felhasználó projektje)
const targetDir = process.env.INIT_CWD || process.cwd();

// Ha a csomag könyvtárában vagyunk, ne másoljunk
if (targetDir === packageDir) {
  console.log('⏭️  Telepítés átugorva (a csomag tulajdon könyvtárában van)');
  process.exit(0);
}

// Másolandó fájlok
const filesToCopy = ['index.js', 'models.js', 'routes.js', '.env', 'Backend teszt.json'];

console.log('📁 Sablonfájlok másolása...\n');

function resolveLatestDependencies(dependencies = {}) {
  const latestDependencies = {};

  Object.keys(dependencies).forEach(depName => {
    try {
      const version = execSync(`npm view ${depName} version`, {
        stdio: ['ignore', 'pipe', 'ignore'],
        encoding: 'utf8'
      }).trim();

      latestDependencies[depName] = version;
    } catch (error) {
      // Ha a lekérdezés nem sikerül, marad a sablonban lévő verzió.
      latestDependencies[depName] = dependencies[depName];
    }
  });

  return latestDependencies;
}

function prepareGeneratedPackageJson(packageJson) {
  packageJson.name = 'my-app';
  packageJson.version = '0.1.0';
  packageJson.author = '';
  packageJson.dependencies = resolveLatestDependencies(packageJson.dependencies);
  delete packageJson.bin;
  delete packageJson.repository;
}

filesToCopy.forEach(file => {
  const src = path.join(packageDir, file);
  const dest = path.join(targetDir, file);
  
  // Ne írjuk felül, ha már létezik
  if (!fs.existsSync(dest) && fs.existsSync(src)) {
    fs.copyFileSync(src, dest);
    console.log(`✓ ${file} másolt`);
  } else if (fs.existsSync(dest)) {
    console.log(`⏭️  ${file} már létezik, kihagyva`);
  }
});

// package.json másolása és módosítása
const srcPackageJson = path.join(packageDir, 'package.json');
const destPackageJson = path.join(targetDir, 'package.json');

if (fs.existsSync(destPackageJson)) {
  console.log(`⏭️  package.json már létezik, kihagyva`);
} else if (fs.existsSync(srcPackageJson)) {
  const packageJson = JSON.parse(fs.readFileSync(srcPackageJson, 'utf8'));

  prepareGeneratedPackageJson(packageJson);

  fs.writeFileSync(destPackageJson, JSON.stringify(packageJson, null, 2));
  console.log(`✓ package.json másolt és módosított`);
}

console.log('\n✅ Kész!\n');
console.log('Következő lépések:');
console.log('1. npm install (függőségek telepítése)');
console.log('2. .env fájl konfigurálása');
console.log('3. npm start (szerver indítása)\n');
